INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7078686, 1076119, 114285, '<td valign="top">Really gorgeous shot, I may have found the blue or the red. The dof is amazing.</td>', 'Really gorgeous shot, I may have found the blue or the red. The dof is amazing.', '2013-07-30 06:59:51.000000', NULL, 1),
(7078690, 1076191, 166415, '<td valign="top">Stunning!!!</td>', 'Stunning!!!', '2013-07-30 07:40:51.000000', NULL, 1),
(7078703, 1076620, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>This photo has great texture on the wood doors. The faded and peeling paint gives a great sense of age and roughness. It complements ''old glory'' seen hanging in the window panels. Shame the number isn''t higher (say like 1811 or some such) that it would point to a time in American history. The shot is taken off to the side and the angle of the window panels slant off at a diagonal. As I sit here, there are times I like the diagonal for it adds visual interest. At other times, it bothers me that it is not on the straight and level.</td>', 'Voted earlier coming back to comment. This photo has great texture on the wood doors. The faded and peeling paint gives a great sense of age and roughness. It complements ''old glory'' seen hanging in the window panels. Shame the number isn''t higher (say like 1811 or some such) that it would point to a time in American history. The shot is taken off to the side and the angle of the window panels slant off at a diagonal. As I sit here, there are times I like the diagonal for it adds visual interest. At other times, it bothers me that it is not on the straight and level.', '2013-07-30 09:03:42.000000', NULL, 1),
(7078705, 1076550, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>Fabulous details on the inner portions of this flower and the ant climbing around on it. I think the composition would be even stronger had the crop been a square to keep the eye focused on your main subjects and have them fully dominate the frame. The rectangular ratio you have here now has too much negative space that does little for the composition overall.</td>', 'Voted earlier coming back to comment. Fabulous details on the inner portions of this flower and the ant climbing around on it. I think the composition would be even stronger had the crop been a square to keep the eye focused on your main subjects and have them fully dominate the frame. The rectangular ratio you have here now has too much negative space that does little for the composition overall.', '2013-07-30 09:07:24.000000', NULL, 1),
(7078707, 1076689, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>upon<br/> <br/>a red wheel<br/>barrow<br/> <br/>glazed with rain<br/>water<br/> <br/>beside the white<br/>chickens. <br/> <br/>What a great find! Now it is not beside white chickens, but it is near a white laundry basket and some hanging laundry that is white or near white. The faded saturation of the final composition gives this a sense of age; an old photograph where the rich colors have faded with time. In my opinion, this has such great potential (7 and above) if only the main elements were better composed. I get the sense that this was not your property so that you could not go and rearrange the main subjects. However, what could have been done is to move off to the right to take it at an angle where that small tree trunk doesn''t cut across the wheelbarrow. Or, if possible, step up to where the small tree is and take the shot from there so it doesn''t interrupt the view of the red wheelbarrow. Also a closer zoom could have the red wheelbarrow fill the bottom right corner of the frame while the laundry would stretch across the frame from left to right.</td>', 'Voted earlier coming back to comment. upon a red wheelbarrow glazed with rainwater beside the whitechickens.  What a great find! Now it is not beside white chickens, but it is near a white laundry basket and some hanging laundry that is white or near white. The faded saturation of the final composition gives this a sense of age; an old photograph where the rich colors have faded with time. In my opinion, this has such great potential (7 and above) if only the main elements were better composed. I get the sense that this was not your property so that you could not go and rearrange the main subjects. However, what could have been done is to move off to the right to take it at an angle where that small tree trunk doesn''t cut across the wheelbarrow. Or, if possible, step up to where the small tree is and take the shot from there so it doesn''t interrupt the view of the red wheelbarrow. Also a closer zoom could have the red wheelbarrow fill the bottom right corner of the frame while the laundry would stretch across the frame from left to right.', '2013-07-30 09:24:44.000000', NULL, 1),
(7078712, 1076672, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>Wonderfully sharp details in that toy bunny that shows off the knitted pattern nicely. Lighting and details are great. The child''s fierce gaze in the background and the thrust forward ''in your face'' presentation of the bunny does compliment the title very well. This toy has to be a tough bunny to withstand the rough play that grip around it''s neck and shoulder communicates; in other words, that grip is not a cuddle sort but a rough and tumble sort. There have been a few times that I see the toy bunny''s expression as one that pleads to the audience ''Help me!" While the toy may be a tough bunny it still seeks relief from the rough handling.</td>', 'Voted earlier coming back to comment. Wonderfully sharp details in that toy bunny that shows off the knitted pattern nicely. Lighting and details are great. The child''s fierce gaze in the background and the thrust forward ''in your face'' presentation of the bunny does compliment the title very well. This toy has to be a tough bunny to withstand the rough play that grip around it''s neck and shoulder communicates; in other words, that grip is not a cuddle sort but a rough and tumble sort. There have been a few times that I see the toy bunny''s expression as one that pleads to the audience ''Help me!" While the toy may be a tough bunny it still seeks relief from the rough handling.', '2013-07-30 09:36:17.000000', NULL, 1),
(7078720, 1076623, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>Lighting, color, and angle of the composition are fabulous. The line up of adirondack chairs from near to far leads the eye to those two in the backdrop that do indeed invite the viewer to ''take a seat''. Those rich reds of the Adirondacks really pops off of the white walls of the house. The inclusion of the window in the frame is a nice touch because the reflection shows me the greenery that surrounds the outdoors. Taking a seat on this deck promises both relaxation and a nice view of nature to boot.</td>', 'Voted earlier coming back to comment. Lighting, color, and angle of the composition are fabulous. The line up of adirondack chairs from near to far leads the eye to those two in the backdrop that do indeed invite the viewer to ''take a seat''. Those rich reds of the Adirondacks really pops off of the white walls of the house. The inclusion of the window in the frame is a nice touch because the reflection shows me the greenery that surrounds the outdoors. Taking a seat on this deck promises both relaxation and a nice view of nature to boot.', '2013-07-30 09:43:07.000000', NULL, 1),
